 "content": "from collections import Counter


def transform(grid):
    """Color each row's trailing background run with 1 after its last mark."""
    if not grid:
        return []
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        marked = [c for c, value in enumerate(row) if value != background]
        if marked:
            for c in range(marked[-1] + 1, len(row)):
                out[r][c] = 1
    return out
